require __DIR__.'/includes/bootstrap.php';$u=require_login();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='profile'){$username=trim((string)($_POST['username']??''));$email=trim((string)($_POST['email']??''));if($username===''||mb_strlen($username)>15||!preg_match('/^[\p{L}\p{N}_ .-]{1,15}$/u',$username))$errors[]='Pseudo invalide (1 à 15 caractères).';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>254)$errors[]='Adresse e-mail invalide.';if(!$errors){$s=$pdo->prepare('SELECT id FROM users WHERE username=:u AND id<>:id');$s->execute(['u'=>$username,'id'=>$u['id']]);if($s->fetch())$errors[]='Ce pseudo est déjà pris.';else{$pdo->prepare('UPDATE users SET username=:u,email=:e WHERE id=:id')->execute(['u'=>$username,'e'=>$email,'id'=>$u['id']]);$_SESSION['user']['username']=$username;$_SESSION['user']['email']=$email;$u=$_SESSION['user'];flash('Profil mis à jour.','success');redirect('account.php');}}}elseif($action==='delete_account'){$confirmDelete=(string)($_POST['confirm_delete']??'');$deletePassword=(string)($_POST['delete_password']??'');$s=$pdo->prepare('SELECT password_hash FROM users WHERE id=:id');$s->execute(['id'=>$u['id']]);$row=$s->fetch();if($confirmDelete!=='SUPPRIMER')$errors[]='Tape exactement SUPPRIMER pour confirmer.';elseif(!$row||!password_verify($deletePassword,$row['password_hash']))$errors[]='Mot de passe incorrect.';else{$pdo->prepare('DELETE FROM users WHERE id=:id')->execute(['id'=>$u['id']]);$_SESSION=[];session_destroy();header('Location: '.url('index.php'));exit;}}elseif($action==='password'){$old=(string)($_POST['old_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['new_password_confirm']??'');$s=$pdo->prepare('SELECT password_hash FROM users WHERE id=:id');$s->execute(['id'=>$u['id']]);$row=$s->fetch();if(!$row||!password_verify($old,$row['password_hash']))$errors[]='Mot de passe actuel incorrect.';elseif($new==='')$errors[]='Le nouveau mot de passe ne peut pas être vide.';elseif($new!==$confirm)$errors[]='Les nouveaux mots de passe ne correspondent pas.';else{$algo=defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT;$pdo->prepare('UPDATE users SET password_hash=:p WHERE id=:id')->execute(['p'=>password_hash($new,$algo),'id'=>$u['id']]);flash('Mot de passe modifié.','success');redirect('account.php');}}}
$u=current_user();$pageTitle='Mon compte';require __DIR__.'/includes/header.php';?>
